import { T, type TLShape } from "tldraw";

// The patched tldraw validator is the single definition of a valid link, so geo
// shapes and text shapes agree on what obsidian:// forms are accepted.
export const isAllowedTextLinkUrl = (value: string): boolean =>
  T.linkUrl.isValid(value);

export const isObsidianUrl = (url: string): boolean => {
  try {
    return new URL(url).protocol.toLowerCase() === "obsidian:";
  } catch {
    return false;
  }
};

// Returns the parsed form: `new URL` strips leading control characters, so a
// raw value could pass the validator and fail a prefix test further on.
export const getTextShapeLinkUrl = (shape: TLShape): string => {
  const raw = (shape.meta as { url?: unknown }).url;
  if (typeof raw !== "string" || !isAllowedTextLinkUrl(raw)) return "";
  try {
    return new URL(raw).toString();
  } catch {
    return "";
  }
};

import type { Editor } from "tldraw";
import DiscourseGraphPlugin from "~/index";
import {
  parseObsidianOpenUrl,
  resolveObsidianUrlToFile,
} from "~/components/canvas/utils/externalContentHandlers";
import {
  openFileInNewLeaf,
  openFileInNewTab,
  openFileInSidebar,
} from "~/components/canvas/utils/openFileUtils";
import { showToast } from "~/components/canvas/utils/toastUtils";
import { isObsidianUrl } from "~/components/canvas/utils/textShapeLink";

type NavigateLinkDetail = {
  url: string;
  metaKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
};

// Patched tldraw dispatches this from every HyperlinkButton, so one listener
// covers text-shape links and geo/note/image links alike.
export const NAVIGATE_LINK_EVENT = "tldraw.navigate-link";

export const registerLinkNavigation = (
  editor: Editor,
  plugin: DiscourseGraphPlugin,
): (() => void) => {
  const container = editor.getContainer();

  const onNavigate = (event: Event) => {
    const { url, metaKey, ctrlKey, altKey } = (event as CustomEvent).detail as
      | NavigateLinkDetail
      | undefined as NavigateLinkDetail;
    if (!isObsidianUrl(url)) return;
    // Cancelling tells tldraw to preventDefault, so the URI never reaches the
    // OS handler and we keep the cross-vault check below.
    event.preventDefault();

    const parsed = parseObsidianOpenUrl(url);
    const file = parsed ? resolveObsidianUrlToFile(plugin, parsed) : null;
    if (!file) {
      showToast({
        severity: "warning",
        title: "Cannot open link",
        description: "The linked file is not in this vault",
      });
      return;
    }

    // Mirrors the discourse-node gestures in TldrawViewComponent.
    const open = altKey
      ? openFileInNewLeaf
      : metaKey || ctrlKey
        ? openFileInNewTab
        : openFileInSidebar;
    void open(plugin.app, file);
    editor.selectNone();
  };

  container.addEventListener(NAVIGATE_LINK_EVENT, onNavigate);
  return () => container.removeEventListener(NAVIGATE_LINK_EVENT, onNavigate);
};

import { HyperlinkButton, useEditor, useValue, TLShapeId } from "tldraw";
import { getTextShapeLinkUrl } from "~/components/canvas/utils/textShapeLink";

// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
const HIDE_BELOW_ZOOM = 0.32;

type TextLink = { id: TLShapeId; url: string; left: number; top: number };

// Rendered here, not on a custom shape util, so the stock text shape stays
// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
export const TextLinkOverlay = () => {
  const editor = useEditor();

  const links = useValue<TextLink[]>(
    "textShapeLinks",
    () => {
      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
      const viewport = editor.getViewportPageBounds();
      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
        if (shape.type !== "text" || editor.isShapeHidden(shape)) return [];
        const url = getTextShapeLinkUrl(shape);
        if (!url) return [];
        const bounds = editor.getShapePageBounds(shape.id);
        if (!bounds || !viewport.includes(bounds)) return [];
        const topRight = editor.pageToViewport({
          x: bounds.maxX,
          y: bounds.minY,
        });
        const bottomRight = editor.pageToViewport({
          x: bounds.maxX,
          y: bounds.maxY,
        });
        return [
          {
            id: shape.id,
            url,
            left: topRight.x,
            top: (topRight.y + bottomRight.y) / 2,
          },
        ];
      });
    },
    [editor],
  );

  return (
    <div className="dg-text-link-overlay">
      {links.map(({ id, url, left, top }) => (
        <div
          key={id}
          className="dg-text-link-anchor"
          style={{ left: `${left}px`, top: `${top}px` }}
        >
          <HyperlinkButton url={url} />
        </div>
      ))}
    </div>
  );
};

